package com.greenocean.backend;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.wellbeing.service.*;
import com.greenocean.backend.wellbeing.repository.WellbeingRepository;
import com.greenocean.backend.auth.repository.UserRepository;
import com.greenocean.backend.auth.service.TokenService;
import com.greenocean.backend.account.repository.AccountRepository;
import com.greenocean.backend.account.service.AccountService;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseO3LearningTest {
 @Autowired JdbcTemplate db;@Autowired GrowthLibrary library;@Autowired LearningCourses learning;@Autowired ReviewedQuestions questions;@Autowired PrivateWellbeing privateData;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired WellbeingRepository wellbeing;@Autowired AccountRepository erasure;@Autowired AccountService archives;@Autowired org.springframework.test.web.servlet.MockMvc mvc;
 PhaseIFixtures.Actor author,reviewer,issuer,learner,other;
 @BeforeEach void setup(){PhaseIFixtures.region(db);author=PhaseIFixtures.member(db,users,tokens);reviewer=PhaseIFixtures.member(db,users,tokens);issuer=PhaseIFixtures.member(db,users,tokens);learner=PhaseIFixtures.member(db,users,tokens);other=PhaseIFixtures.member(db,users,tokens);role(issuer.id(),"ADMIN");role(reviewer.id(),"MODERATOR");for(String action:List.of("DRAFT","SUBMIT"))grant(author.id(),action);for(String action:List.of("REVIEW","APPROVE","PUBLISH","RETIRE"))grant(reviewer.id(),action);}
 void role(UUID who,String name){db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name=? ON CONFLICT DO NOTHING",who,name);}
 void grant(UUID who,String action){library.grant(issuer.id(),new GrowthLibrary.Grant(who,action,"GENERAL","Synthetic isolated curriculum permission",Instant.now().plusSeconds(3600)));}
 Map<String,Object> lesson(String title,boolean quiz){var row=new LinkedHashMap<String,Object>();row.put("title",title);row.put("body","Choose one manageable action that matters to you. Consider the time and resources you have. You may adapt or skip this practice freely; a missed day does not make the goal a failure.");row.put("objectives","Distinguish a manageable plan from pressure.");row.put("minutes",5);row.put("required",true);if(quiz)row.put("exercise",Map.of("type","CHOICE","instruction","Which option preserves choice?","choices",List.of("Choose one manageable action","Punish a missed day"),"correctIndex",0,"explanation","A manageable action respects autonomy; missed days have no penalty."));return row;}
 Map<String,Object> doc(){var d=new LinkedHashMap<String,Object>();d.put("kind","COURSE");d.put("title","Synthetic manageable planning");d.put("summary","Original general educational material, not treatment.");d.put("language","en");d.put("scope","GENERAL");d.put("topic","Planning");d.put("why","General education about adapting small steps");d.put("audience","ADULT");d.put("rights","Original synthetic QA curriculum");d.put("sources",List.of("https://example.org/educational-source"));d.put("modules",List.of(Map.of("title","Small steps","lessons",List.of(lesson("Choose a step",true),lesson("Adapt without pressure",false)))));return d;}
 UUID create(){return(UUID)library.create(author.id(),new GrowthLibrary.Draft(doc(),0,0)).get("resource_id");}
 GrowthLibrary.Decision decision(UUID id,String action){var r=library.editorial(author.id(),id);return new GrowthLibrary.Decision(((Number)r.get("revision")).intValue(),((Number)r.get("etag")).longValue(),action,"Synthetic independent curriculum source/rights review",true,true);}
 void publish(UUID id){library.transition(author.id(),id,decision(id,"SUBMIT"));library.transition(reviewer.id(),id,decision(id,"APPROVE"));library.transition(reviewer.id(),id,decision(id,"PUBLISH"));}
 UUID course(){UUID id=create();publish(id);return id;}
 List<UUID> keys(UUID id){int revision=((Number)library.editorial(author.id(),id).get("revision")).intValue();return db.queryForList("SELECT lesson_key FROM learning_lessons(?,?) ORDER BY module_position,lesson_position",UUID.class,id,revision);}
 Map<String,Object> open(UUID id,UUID key){return learning.open(learner.id(),id,key);}
 Map<String,Object> complete(UUID id,UUID key){var l=open(id,key);return learning.complete(learner.id(),id,key,new LearningCourses.Completion((String)l.get("content_digest"),true));}
 Map<String,Object> forkDoc(UUID id){return new LinkedHashMap<>((Map<String,Object>)library.editorial(author.id(),id).get("document"));}
 void fork(UUID id,Map<String,Object> doc){var row=library.editorial(author.id(),id);library.edit(author.id(),id,new GrowthLibrary.Draft(doc,((Number)row.get("revision")).intValue(),((Number)row.get("etag")).longValue()),true);publish(id);}
 @Test @Tag("happy") void actualHierarchyAndLegacyCatalogShowOnlyRealReviewedLessons(){UUID id=course();assertThat(learning.progress(learner.id(),id).get("requiredLessons")).isEqualTo(2L);assertThat(wellbeing.growthPaths(learner.id())).hasSize(1);assertThat(wellbeing.growthPaths(learner.id()).getFirst().lessonCount()).isEqualTo(2);assertThat(wellbeing.growthPaths(learner.id()).getFirst().authorName()).isEqualTo("Synthetic peer");}
 @Test @Tag("malicious") void unpublishedMaterialCannotBeOpenedOrCompleted(){UUID id=create(),key=keys(id).getFirst();assertThatThrownBy(()->learning.open(learner.id(),id,key)).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->learning.complete(learner.id(),id,key,new LearningCourses.Completion("forged",true))).isInstanceOf(NotFoundException.class);}
 @Test @Tag("confused") void explicitOpeningAndMeaningfulAcknowledgementAreRequired(){UUID id=course(),key=keys(id).getFirst();String digest=db.queryForObject("SELECT content_digest FROM learning_lessons(?,1) WHERE lesson_key=?",String.class,id,key);assertThatThrownBy(()->learning.complete(learner.id(),id,key,new LearningCourses.Completion(digest,true))).isInstanceOf(ConflictException.class);open(id,key);assertThatThrownBy(()->learning.complete(learner.id(),id,key,new LearningCourses.Completion(digest,false))).isInstanceOf(IllegalArgumentException.class);}
 @Test @Tag("happy") void progressDerivesFromActualRequiredCompletionsWithoutPrivateWriting(){UUID id=course();var keys=keys(id);complete(id,keys.getFirst());assertThat(learning.progress(learner.id(),id).get("percent")).isEqualTo(50);complete(id,keys.getLast());assertThat(learning.progress(learner.id(),id).get("percent")).isEqualTo(100);assertThat(db.queryForObject("SELECT count(*) FROM learning_course_completions WHERE owner_id=?",Integer.class,learner.id())).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_journal_entries WHERE user_id=?",Integer.class,learner.id())).isZero();}
 @Test @Tag("malicious") void repeatedCompletionReturnsOneGenuineEvent(){UUID id=course(),key=keys(id).getFirst();var first=complete(id,key);var second=complete(id,key);assertThat(second.get("completionId")).isEqualTo(first.get("completionId"));assertThat(db.queryForObject("SELECT count(*) FROM learning_lesson_completions WHERE owner_id=?",Integer.class,learner.id())).isEqualTo(1);}
 @Test @Tag("malicious") void otherAccountsNeverInheritLearningProgressOrHistory(){UUID id=course();complete(id,keys(id).getFirst());assertThat(learning.progress(other.id(),id).get("percent")).isEqualTo(0);assertThat(learning.history(other.id(),0).get("lessons")).asList().isEmpty();}
 @Test @Tag("creative") void retirementStopsNewCompletionButPreservesActualHistory(){UUID id=course();var keys=keys(id);complete(id,keys.getFirst());var last=open(id,keys.getLast());library.transition(reviewer.id(),id,decision(id,"RETIRE"));assertThatThrownBy(()->learning.complete(learner.id(),id,keys.getLast(),new LearningCourses.Completion((String)last.get("content_digest"),true))).isInstanceOf(NotFoundException.class);assertThat(learning.history(learner.id(),0).get("lessons")).asList().hasSize(1);}
 @Test @Tag("creative") void unchangedLessonCompletionSurvivesNewRevision(){UUID id=course();complete(id,keys(id).getFirst());var d=forkDoc(id);d.put("summary","A revised course summary without silently changing completed lesson content.");fork(id,d);assertThat(learning.progress(learner.id(),id).get("percent")).isEqualTo(50);assertThat(learning.history(learner.id(),0).get("lessons")).asList().hasSize(1);}
 @Test @Tag("creative") void newRequiredMaterialChangesCurrentProgressWithoutErasingPriorCompletion(){UUID id=course();for(UUID key:keys(id))complete(id,key);var d=forkDoc(id);var modules=new ArrayList<>((List<Map<String,Object>>)d.get("modules"));var module=new LinkedHashMap<>(modules.getFirst());var lessons=new ArrayList<>((List<Map<String,Object>>)module.get("lessons"));lessons.add(lesson("New reviewed practice",false));module.put("lessons",lessons);modules.set(0,module);d.put("modules",modules);fork(id,d);assertThat(learning.progress(learner.id(),id).get("percent")).isEqualTo(66);assertThat(learning.history(learner.id(),0).get("courses")).asList().hasSize(1);}
 @Test @Tag("malicious") void currentContentDigestPreventsStaleLessonReplay(){UUID id=course();var key=keys(id).getFirst();var old=open(id,key);var d=forkDoc(id);var modules=(List<Map<String,Object>>)d.get("modules");var lessons=(List<Map<String,Object>>)modules.getFirst().get("lessons");lessons.getFirst().put("body","New genuine reviewed material explains how a manageable plan can change when resources change. This content requires a new explicit reading acknowledgement, without asking for private disclosure.");fork(id,d);assertThatThrownBy(()->learning.complete(learner.id(),id,key,new LearningCourses.Completion((String)old.get("content_digest"),true))).isInstanceOf(ConflictException.class);}
 @Test @Tag("malicious") void foreignLessonIdentityCannotBeReboundToAnotherCourse(){UUID first=course();var d=doc();((Map<String,Object>)((List<?>)((Map<?,?>)((List<?>)d.get("modules")).getFirst()).get("lessons")).getFirst()).put("key",keys(first).getFirst().toString());assertThatThrownBy(()->library.create(author.id(),new GrowthLibrary.Draft(d,0,0))).isInstanceOf(IllegalArgumentException.class);}
 @Test @Tag("malicious") void noAdultEligibilityBypass(){UUID id=course();db.update("UPDATE account_eligibility SET age_result='INELIGIBLE' WHERE user_id=?",learner.id());assertThatThrownBy(()->learning.course(learner.id(),id)).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("confused") void optionalKnowledgeCheckIsRepeatableAndNeverAdvancesLessonPercent(){UUID id=course(),key=keys(id).getFirst();var l=open(id,key);String digest=(String)l.get("content_digest");assertThat(learning.check(learner.id(),id,key,new LearningCourses.Check(digest,1)).get("correct")).isEqualTo(false);assertThat(learning.check(learner.id(),id,key,new LearningCourses.Check(digest,0)).get("correct")).isEqualTo(true);learning.check(learner.id(),id,key,new LearningCourses.Check(digest,0));assertThat(db.queryForObject("SELECT count(*) FROM learning_exercise_completions WHERE owner_id=?",Integer.class,learner.id())).isEqualTo(1);assertThat(learning.progress(learner.id(),id).get("percent")).isEqualTo(0);}
 @Test @Tag("malicious") void originalArbitraryProgressHttpContractIsClosed()throws Exception{UUID id=course();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/wellbeing/growth-paths/"+id).header("Authorization","Bearer "+learner.token()).contentType("application/json").content("{\"progress\":100}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isConflict());assertThat(learning.progress(learner.id(),id).get("percent")).isEqualTo(0);}
 UUID prompt(String body){var q=questions.save(author.id(),null,new ReviewedQuestions.Input(body,"en","Original synthetic general question",List.of(),0),false);UUID id=(UUID)q.get("id");publishPrompt(id);return id;}
 void publishPrompt(UUID id){long etag=((Number)db.queryForMap("SELECT etag FROM wellbeing_prompt_versions WHERE id=?",id).get("etag")).longValue();questions.act(author.id(),id,new ReviewedQuestions.Action("SUBMIT",etag,"Synthetic submission",false,false));questions.act(reviewer.id(),id,new ReviewedQuestions.Action("APPROVE",etag+1,"Independent synthetic question review",true,true));questions.act(reviewer.id(),id,new ReviewedQuestions.Action("PUBLISH",etag+2,"Synthetic reviewed question publication",true,true));}
 @Test @Tag("happy") void questionRevisionNeverRewritesHistoricalPrivateAnswers(){UUID old=prompt("What small optional step would you like to consider?");prompt("What helped you feel comfortable today?");prompt("What would you like to understand better?");var day=privateData.daily(learner.id(),"UTC","en");UUID set=(UUID)((Map<?,?>)day.get("set")).get("id");var selected=(List<Map<String,Object>>)day.get("items");int position=((Number)selected.stream().filter(q->old.equals(q.get("prompt_id"))).findFirst().orElseThrow().get("position")).intValue();privateData.answer(learner.id(),new PrivateWellbeing.Answer(set,position,"Private learner response must not reach editorial staff",-1),false);var newVersion=questions.save(author.id(),old,new ReviewedQuestions.Input("A new optional general question with new wording?","en","Original synthetic revised question",List.of(),3),true);publishPrompt((UUID)newVersion.get("id"));assertThat(db.queryForObject("SELECT p.body FROM wellbeing_daily_questions q JOIN wellbeing_prompt_versions p ON p.id=q.prompt_id WHERE q.set_id=? AND q.position=?",String.class,set,position)).isEqualTo("What small optional step would you like to consider?");assertThat(questions.workspace(reviewer.id(),0).toString()).doesNotContain("Private learner response");assertThat(archives.archive(author.id()).privateWellbeing().toString()).doesNotContain("Private learner response");}
 @Test @Tag("confused") void retiredQuestionsAreNotSelectedForNewDaysOrOwners(){UUID retired=prompt("A first optional prompt?");prompt("A second optional prompt?");prompt("A third optional prompt?");questions.act(reviewer.id(),retired,new ReviewedQuestions.Action("RETIRE",3,"Synthetic retirement",true,true));assertThat(privateData.daily(learner.id(),"UTC","en").get("available")).isEqualTo(false);}
 @Test @Tag("malicious") void questionAuthorCannotApproveTheirOwnWork(){role(author.id(),"MODERATOR");grant(author.id(),"REVIEW");grant(author.id(),"APPROVE");UUID id=(UUID)questions.save(author.id(),null,new ReviewedQuestions.Input("A synthetic optional prompt?","en","Original QA",List.of(),0),false).get("id");questions.act(author.id(),id,new ReviewedQuestions.Action("SUBMIT",0,"Synthetic submit",false,false));assertThatThrownBy(()->questions.act(author.id(),id,new ReviewedQuestions.Action("APPROVE",1,"Self approval",true,true))).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("happy") void rightsEraseOwnLearningWhileCreatorErasurePreservesDeidentifiedLearnerMilestones(){UUID id=course();for(UUID key:keys(id))complete(id,key);assertThat(archives.archive(learner.id()).privateWellbeing().get("lessonCompletions")).asList().hasSize(2);erasure.erase(author.id());assertThat(learning.history(learner.id(),0).get("lessons")).asList().hasSize(2);assertThat(db.queryForObject("SELECT count(*) FROM learning_lesson_completions WHERE owner_id=? AND course_id IS NULL",Integer.class,learner.id())).isEqualTo(2);erasure.erase(learner.id());assertThat(db.queryForObject("SELECT count(*) FROM learning_lesson_completions WHERE owner_id=?",Integer.class,learner.id())).isZero();}
}
